import fitz
for p in ['paper1.pdf','paper2.pdf','paper3.pdf']:
    doc = fitz.open(p)
    print('==='*10, p)
    # Print last page too (may have acknowledgements/venue)
    text = doc[0].get_text()
    # Check for arxiv-style vertical text (header on each page)
    for i in range(min(3, len(doc))):
        t = doc[i].get_text()
        for line in t.split('\n'):
            if 'arxiv' in line.lower() or 'preprint' in line.lower() or 'copyright' in line.lower() or 'icml' in line.lower() or 'interspeech' in line.lower() or 'proceedings' in line.lower():
                print(f'pg{i}:', repr(line))
    doc.close()
"", "summary": "Look for arxiv headers and venue strings"}

