{"command": "cd /root && python3 -c "
import fitz, re
for p in ['paper1.pdf','paper2.pdf','paper3.pdf']:
    doc = fitz.open(p)
    full = '\n'.join(pg.get_text() for pg in doc)
    print('==='*10, p)
    for m in re.finditer(r'https?://\S+', full):
        s = m.group(0)
        if 'github' in s or 'huggingface' in s or 'linkedin' in s or '.edu' in s or '~' in s:
            print(repr(s))
    doc.close()
"", "summary": "Find identifying URLs"}

