{"command": "cd /root && python3 -c "
import fitz, re
names = {
  'paper1.pdf': ['Yueqian Lin','Zhengmian Hu','Qinsi Wang','Yudong Liu','Hengfan Zhang','Jayakumar Subramanian','Nikos Vlassis','Hai \"Helen\" Li','Hai Li','Yiran Chen'],
  'paper2.pdf': ['Jiatong Shi','Yueqian Lin','Xinyi Bai','Keyi Zhang','Yuning Wu','Yuxun Tang','Yifeng Yu','Qin Jin','Shinji Watanabe'],
  'paper3.pdf': ['Yueqian Lin','Yuzhe Fu','Jingyang Zhang','Yudong Liu','Jianyi Zhang','Jingwei Sun','Hai Li','Yiran Chen'],
}
for p, ns in names.items():
    doc = fitz.open(p)
    full = '\n'.join(pg.get_text() for pg in doc)
    print('==='*5, p)
    for n in ns:
        cnt = full.count(n)
        print(f'  {n!r}: {cnt}')
    doc.close()
"", "summary": "Count name occurrences in each paper"}

